  function norm(s){return String(s||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").trim()}
  function root(s){
    var x=norm(s).replace(/\b(the|a|an|of|to|in|on|for|and|with)\b/g," ").replace(/\s+/g," ").trim();
    return x.replace(/(isations?|izations?|ation|tion|sion|ment|ness|ity|ive|al|ous|ful|less|edly|edly|ing|ed|er|or|ly|s)$/,"");
  }
